# uuid7.map — the functions libuuid7.so exports, under the version node UUID7_<major> (the soname major): exactly the
# functions app/uuid7.h declares (the `function` lines of abi/layout.txt; utils/check_abi.sh --exports refuses any difference).
# The test hooks are exported only from a library built with them. Everything else stays local. The .a is unaffected.
UUID7_1 {
  global:
    uuid7_clock_failure_count;
    uuid7_gen;
    uuid7_init;
    uuid7_raise_floor;
    uuid7_set_rng_func;
    uuid7_test_*;   /* the test hooks: compiled only with -DUUID7_TESTING (ENABLE_TEST_HOOKS=1), never in a release */
  local:
    *;
};
